WITH base AS (SELECT *, CAST(is_flagged AS INT) is_flagged_flag, CAST(is_flagged AS INT) is_flagged_flag_2, COALESCE(merchant, 'DIRECT') resolved_merchant FROM transactions WHERE txn_time > TO_DATE('2023-06-30') AND merchant IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM base), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged), joined AS (SELECT a.id, a.account_id, a.txn_type, a.amount, a.txn_time, a.is_flagged_flag, a.is_flagged_flag_2, a.resolved_merchant, a.new_group_flag, p2.status, p2.balance, p2.account_type FROM sessionized a INNER JOIN accounts p2 ON a.account_id = p2.id), with_dims AS (SELECT s.id, s.account_id, s.txn_type, s.amount, s.is_flagged_flag_2, s.status, s.account_type, a.balance AS account_balance, a.opened_date, a.account_type AS account_account_type FROM joined s LEFT JOIN accounts a ON s.account_id = a.id WHERE a.opened_date BETWEEN '2023-08-25' AND '2023-09-01'), latest AS (SELECT id, account_id, txn_type, status, account_type, account_balance, opened_date FROM with_dims QUALIFY ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY opened_date DESC NULLS LAST, id) = 1) SELECT id, account_id, account_type, account_balance, opened_date, LEAD(account_balance, 1) OVER (PARTITION BY txn_type ORDER BY opened_date, id) next_account_balance, CUME_DIST() OVER (PARTITION BY status ORDER BY account_balance) account_balance_cume_dist FROM latest
